import io
from werkzeug.sansio.multipart import MultipartDecoder, Data, Field, File, Epilogue, NeedData
from werkzeug.formparser import MultiPartParser, FormDataParser, parse_form_data
from werkzeug.wrappers import Request
from werkzeug.exceptions import RequestEntityTooLarge

boundary = b'a.+[b]?$'
payloads = [b'', b'\r', b'\n', b'\r\n', bytes(range(256)), b'\0'*65535+b'\r']
payloads += [b'start\r\n--'+boundary+x+b'\r\nend' for x in [b'--X', b'--!', b'---', b'----', b' \tX', b'-- \tX']]

def body(payload, nl=b'\r\n', pad=b' \t', end=b'\r\n'):
    return b'--'+boundary+pad+nl+b'Content-Disposition: form-data; name="x"; filename="a"'+nl+nl+payload+nl+b'--'+boundary+b'--'+pad+end

def decode(chunks):
    p=MultipartDecoder(boundary)
    result=[]
    completions=0
    for chunk in [*chunks, None]:
        p.receive_data(chunk)
        while True:
            e=p.next_event()
            if isinstance(e, NeedData): break
            if isinstance(e, Data):
                result.append(e.data)
                completions+=not e.more_data
            if isinstance(e,Epilogue): return b''.join(result), completions
    raise AssertionError('missing epilogue')

for payload in payloads:
    for nl in (b'\r\n', b'\r', b'\n'):
        for end in (nl,b''):
            wire=body(payload,nl,end=end)
            assert decode([wire])==(payload,1)
            assert decode([bytes([x]) for x in wire])==(payload,1)
            if len(wire)<1000:
                for split in range(len(wire)+1):
                    assert decode([wire[:split],wire[split:]])==(payload,1),(payload,nl,end,split)
print('decoder fragmentation matrix passed')

class ShortSink(io.BytesIO):
    def __init__(self): super().__init__(); self.closes=0
    def write(self,b): return super().write(b[:2])
    def close(self): self.closes+=1; super().close()
sinks=[]
def factory(**kw):
    sink=ShortSink(); sinks.append(sink); return sink
p=MultiPartParser(stream_factory=factory, max_file_size=4,max_form_data_size=4,buffer_size=1)
form,files=p.parse(io.BytesIO(body(b'abcd')),boundary,None)
assert files['x'].read()==b'abcd' and sinks[-1].closes==0
for payload in (b'abcde',b'x'*20):
    try: p.parse(io.BytesIO(body(payload)),boundary,None)
    except RequestEntityTooLarge: pass
    else: raise AssertionError('quota')
    assert sinks[-1].closes==1
assert p.parse(io.BytesIO(body(b'abcd')),boundary,None)[1]['x'].read()==b'abcd'
for invalid in (True,False,-1,1.5,'2'):
    for name in ('max_file_size','max_form_data_size'):
        for cls in (MultiPartParser, FormDataParser):
            try: cls(**{name:invalid})
